with actor as materialized(select set_config('request.jwt.claim.sub',(select id::text from public.users where oss_role='master' order by created_at limit 1),true)),
targets as(select * from jsonb_to_recordset('[{"id":"5725","line":4},{"id":"5735","line":4},{"id":"5779","line":3},{"id":"5822","line":4},{"id":"5822","line":5},{"id":"6071","line":2},{"id":"6111","line":4},{"id":"6118","line":5},{"id":"6195","line":6},{"id":"6208","line":5},{"id":"6270","line":6},{"id":"6270","line":7},{"id":"6430","line":3},{"id":"6504","line":6},{"id":"4453","line":6},{"id":"4593","line":6},{"id":"4755","line":4},{"id":"4961","line":6},{"id":"4984","line":2},{"id":"5255","line":2},{"id":"5263","line":4},{"id":"5406","line":3},{"id":"5451","line":4},{"id":"5494","line":5},{"id":"5559","line":5},{"id":"5603","line":4},{"id":"5613","line":4},{"id":"5655","line":3},{"id":"5737","line":6},{"id":"5756","line":3},{"id":"5834","line":2},{"id":"5993","line":5},{"id":"5676","line":2},{"id":"6423","line":3},{"id":"6443","line":3},{"id":"6476","line":5},{"id":"6480","line":5},{"id":"6592","line":5},{"id":"6594","line":3},{"id":"6617","line":6},{"id":"6754","line":6}]'::jsonb)t(id text,line integer))
